type Chunk = { lo: number; hi: number };
type Partial = { lo: number; sum: number };

const chunks: Chunk[] = partition(input, workers);
const parts: Partial[] = await Promise.all(              // dispatch + join
  chunks.map(c => computePart(c))                       // Promise<Partial>
);
const total = parts.reduce((a, p) => a + p.sum, 0);      // combine

// generic pool facade; worker protocol validated at the boundary
const pool = new WorkerPool<Chunk, Partial>('./part-worker.js', workers);
const parts: Partial[] = await Promise.all(          // typed dispatch + join
  chunks.map(chunk => pool.run(chunk))
);
const total = parts.reduce((a, p) => a + p.sum, 0);  // combine

